// Original fibre artwork on a deforming, connected WebGL grid. The image's fine structure remains resolved.
(() => {
 const canvas=document.querySelector('.ai-object');if(!canvas)return;
 const viewport=()=>document.documentElement.style.setProperty('--visual-viewport',document.documentElement.clientWidth+'px');viewport();addEventListener('resize',viewport);
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 const gl=canvas.getContext('webgl',{alpha:true,premultipliedAlpha:true,antialias:true,powerPreference:'low-power'});if(!gl)return;
 const vertex=`precision highp float;
attribute vec2 uv;uniform float time;uniform float aspect;uniform float offsetX;
varying vec2 tex;varying float illumination;
void main(){
 tex=uv;float u=uv.x,v=uv.y;
 float phase=6.2831853*time/18.;
 float upper=smoothstep(.43,.88,v),lower=1.-smoothstep(.18,.48,v);
 float fit=min(.94,aspect/.86);
 vec2 p=(uv-.5)*vec2(1.5,2.);
 p.x*=1.14*(1.+.055*sin(phase-.65*v)*upper+.026*sin(phase-1.4)*lower);
 p.x+=(.025*sin(phase-2.4*v)+.012*sin(phase*2.-v*3.1))*sin(3.14159265*v);
 p.y+=.038*sin(phase+u*2.5)*upper*(u-.35)+.018*sin(phase-1.7)*lower;
 float angle=.022*sin(phase-.4),depth=.10*sin(v*4.6-phase)*sin(3.14159265*u);
 p=mat2(cos(angle),-sin(angle),sin(angle),cos(angle))*p;
 p*=fit/(1.+depth*.18);
 gl_Position=vec4(p.x/aspect+offsetX,p.y,0.,1.);
 illumination=.986+.014*cos(phase*.7+v*2.2);
}`;
 const fragment=`precision highp float;uniform sampler2D artwork;varying vec2 tex;varying float illumination;
 void main(){vec4 color=texture2D(artwork,tex);gl_FragColor=vec4(color.rgb*illumination,color.a);}`;
 function compile(type,source){const shader=gl.createShader(type);gl.shaderSource(shader,source);gl.compileShader(shader);if(!gl.getShaderParameter(shader,gl.COMPILE_STATUS))throw new Error(gl.getShaderInfoLog(shader));return shader;}
 let program;
 try{program=gl.createProgram();gl.attachShader(program,compile(gl.VERTEX_SHADER,vertex));gl.attachShader(program,compile(gl.FRAGMENT_SHADER,fragment));gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw new Error(gl.getProgramInfoLog(program));}
 catch(error){console.warn('[ai-fibre]',error.message);return;}
 gl.useProgram(program);
 const cols=72,rows=112,points=new Float32Array((cols+1)*(rows+1)*2),indices=new Uint16Array(cols*rows*6);
 for(let y=0;y<=rows;y++)for(let x=0;x<=cols;x++){let i=(y*(cols+1)+x)*2;points[i]=x/cols;points[i+1]=y/rows;}
 let at=0;for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){let a=y*(cols+1)+x,b=a+1,c=a+cols+1,d=c+1;indices.set([a,c,b,b,c,d],at);at+=6;}
 gl.bindBuffer(gl.ARRAY_BUFFER,gl.createBuffer());gl.bufferData(gl.ARRAY_BUFFER,points,gl.STATIC_DRAW);
 const loc=gl.getAttribLocation(program,'uv');gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,2,gl.FLOAT,false,0,0);
 gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,gl.createBuffer());gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,indices,gl.STATIC_DRAW);
 gl.bindTexture(gl.TEXTURE_2D,gl.createTexture());gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);
 gl.enable(gl.BLEND);gl.blendFunc(gl.ONE,gl.ONE_MINUS_SRC_ALPHA);gl.clearColor(0,0,0,0);
 const uTime=gl.getUniformLocation(program,'time'),uAspect=gl.getUniformLocation(program,'aspect'),uOffset=gl.getUniformLocation(program,'offsetX');
 let ready=false,visible=false,raf=0,last=0,origin=0;
 const draw=t=>{if(!ready)return;gl.clear(gl.COLOR_BUFFER_BIT);gl.uniform1f(uTime,t);gl.drawElements(gl.TRIANGLES,indices.length,gl.UNSIGNED_SHORT,0);canvas.dataset.motionTime=t.toFixed(2);canvas.dataset.mesh='connected-fibre-artwork-grid';};
 const size=()=>{const b=canvas.getBoundingClientRect(),d=Math.min(2,devicePixelRatio||1);canvas.width=Math.max(1,Math.round(b.width*d));canvas.height=Math.max(1,Math.round(b.height*d));gl.viewport(0,0,canvas.width,canvas.height);gl.uniform1f(uAspect,canvas.width/canvas.height);gl.uniform1f(uOffset,document.documentElement.clientWidth>1000?.36:0.);draw(4);};
 function tick(now){if(!visible||document.hidden||reduced.matches){raf=0;return;}if(!origin)origin=now-4000;if(now-last>15){draw((now-origin)/1000);last=now;}raf=requestAnimationFrame(tick);}
 const run=()=>{if(!ready)return;if(reduced.matches){draw(4);return;}if(visible&&!document.hidden&&!raf)raf=requestAnimationFrame(tick);};
 const source=new Image();source.onload=()=>{gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL,true);gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL,true);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,source);ready=true;canvas.classList.add('is-live');size();run();};source.src='data:image/webp;base64,';
 new ResizeObserver(()=>{size();run();}).observe(canvas);size();document.addEventListener('visibilitychange',run);reduced.addEventListener('change',run);
 if('IntersectionObserver'in window)new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;run();},{threshold:.01}).observe(canvas);else{visible=true;run();}
})();
